#define AA 1.0
#define FOCAL_LEN 1.

#define AO_STR 0.2
#define AO_DIST 0.05
#define AO_POW 2.

vec2 hash12(float p)
{
    vec3 p3 = fract(vec3(p,p,p) * vec3(.1031, .1030, .0973));
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.xx+p3.yz)*p3.zy);
}

vec2 hash22(vec2 p)
{
    vec3 p3 = fract(vec3(p.xyx) * vec3(.1031, .1030, .0973));
    p3 += dot(p3, p3.yzx+33.33);
    return fract((p3.xx+p3.yz)*p3.zy);
}

float mRange(float ai, float aa, float bi, float ba, float x) { return (x-ai)/(aa-ai)*(ba-bi)+bi; } // Maps x between a range of ai-aa to bi-ba
float mRange(vec2 a, vec2 b, float x) { return mRange(a.x, a.y, b.x, b.y, x); }
float sRange(float i, float a, float x) { return x*(a-i)+i; } // Maps x between a range of 0-1 to i-a
float sRange(vec2 a, float x) { return sRange(a.x, a.y, x); }
float eRange(float i, float a, float x) { return (x-i)/(a-i); } // Maps x between a range of i-a to 0-1
float eRange(vec2 a, float x) { return eRange(a.x, a.y, x); }

#define saturate(x) clamp(0.0, 1.0, x)

float sharpstep(float a, float b, float x)
{
    return saturate((x-a)/(b-a));
}

float peak(float a, float b, float x)
{
    return saturate(1.-abs((x-b)/a));
}

float peak2(float a, float b, float m, float x)
{
    x = saturate((x-a)/(b-a));
    return saturate(1.-abs((x-m)/mix(m, 1.-m, step(0., x-m))));
}

mat2 rotMat(float r){ return  mat2(cos(r), -sin(r), sin(r), cos(r)); }


vec3 rotX(vec3 p, float r)
{
    p.yz *= rotMat(r); return p;
}

vec3 rotY(vec3 p, float r)
{
    p.xz *= rotMat(r); return p;
}

vec3 rotZ(vec3 p, float r)
{
    p.xy *= rotMat(r); return p;
}

vec3 rot(vec3 v, in vec3 k, float t) // rotates point v t radians around axis k. See https://en.wikipedia.org/wiki/Rodrigues%27_rotation_formula
{
    k = normalize(k);
    return mix(k*dot(k,v), v, cos(t)) + cross(k, v)*sin(t);
}

struct marchMat
{
    vec3 color;
    int id;
};

struct marchRes
{
    bool hit;
    float depth;
    vec3 pos;
    marchMat mat;
};

void sub(inout float a, float b) { a = max(a, -b); }
void intersect(inout float a, float b) { a = max(a, b); }

void sjoin(inout float a, float b, float k ) // by iq
{
    float h = max( k-abs(a-b), 0.0 )/k;
    a = min( a, b ) - h*h*k*(1.0/4.0);
}

void ssub(inout float d2, float d1, float k ) // by iq
{
    float h = clamp( 0.5 - 0.5*(d2+d1)/k, 0.0, 1.0 );
    d2 = mix( d2, -d1, h ) + k*h*(1.0-h);
}

void sintersect( inout float d2, float d1, float k ) { // by iq
    float h = clamp( 0.5 - 0.5*(d2-d1)/k, 0.0, 1.0 );
    d2 =  mix( d2, d1, h ) + k*h*(1.0-h); }

void marginIntersect(inout float a, float b, float k) { a = max(a-k, b); }
void smarginIntersect(inout float a, float b, float k1, float k2) { a = a-k1; sintersect(a, b, k2); }

vec2 opRepLim2( in vec2 p, in float c, in vec2 l) // by iq
{
    return p-c*clamp(round(p/c),-l,l);
}

vec3 opRepLim3( in vec3 p, in float c, in vec3 l) // by iq
{
    return p-c*clamp(round(p/c),-l+1.,l);
}

float sdSphere(vec3 p, float r)
{
    return length(p)-r;
}

float sdBox( vec3 p, vec3 b ) // by iq
{
  vec3 q = abs(p) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}

float sdBox( vec2 p, vec2 b ) // by iq
{
  vec2 q = abs(p) - b;
  return length(max(q,0.0)) + min(max(q.x,q.y),0.0);
}

float sdBox(vec3 p, vec3 b, float r)
{
    return sdBox(p, b-r)-r;
}

float sdCylinder(vec3 p, vec2 r)
{
    return sdBox(vec2(length(p.xz), p.y),r);
}

float sdCylinder(vec3 p, vec2 r, float b)
{
    return sdBox(vec2(length(p.xz), p.y),r-b)-b;
}

float sdFloor(vec3 p, float y)
{
    return p.y-y;
}

float sdPlane(vec3 p, float y)
{
    return abs(p.y-y);
}

vec3 planeIntersect(in vec3 ro, vec3 rd, float y, out bool hit)
{
    hit = sign(-rd.y) == sign(ro.y-y);
    ro.xz = ro.xz+rd.xz*(y-ro.y)/rd.y;
    return vec3(ro.x, y, ro.z);
}

#define SEARCH 2.

float sdFbmBase(in vec3 p, float j, vec2 r, float s)
{
    float res = 1e20;
    for(vec2 x = vec2(-SEARCH); x.x <= SEARCH; x.x++)
    for(x.y = -SEARCH; x.y <= SEARCH; x.y++)
    {
        vec2 currentCell = (floor(p.xz/s)+x)*s;
        vec2 currentCellOffset = (hash22(currentCell)-0.5)*j;
        float rad = sRange(r, hash22(currentCell+10.).x);
        float currentCellDist = sdSphere(p-vec3(currentCell-currentCellOffset, 0.).xzy, rad);
        sjoin(res, currentCellDist, 1.5);
    }
    return res;
}

float sdFbmBase(in vec3 p, float j, vec2 r, float s, float scale) { return sdFbmBase(p/scale, j, r, s)*scale; }

float sdFbm(vec3 p, float j, vec2 r, float s, float o, float b)
{
    float res = sdPlane(p, 0.);
    float ex = 1.;
    for(float i = 0.; i < o; i++)
    {
        sjoin(res, sdFbmBase(p, j, r, s, ex*2.), b);
        ex *= 0.5;
    }
    return res;
}

float sceneDist(vec3 p, out marchMat outMat)
{
    float scale = 0.05;
    p /= scale;
    //p = rotZ(p, iTime);
    float d = 1e20;
    join(d, sdFbm(p, 5.,vec2(0., 5.), 5., 2., 1.));
    outMat = marchMat(vec3(0.9), 0);
    d *= scale;
    return d;
}

float sceneDist(vec3 p)
{
    marchMat m;
    return sceneDist(p, m);
}

marchRes march(vec3 ro, vec3 rd, float margin, float maxDist, int maxIt)
{
    float depth = 0.0;
    vec3 cp;
    marchRes mres;
    for(int i = 0; i < maxIt && depth < maxDist; i++)
    {
        cp = ro + depth*rd;
        float cd = sceneDist(cp, mres.mat);
        if(cd < margin)
        {
            return marchRes(true, depth, cp, mres.mat);
        }
        depth += cd;
    }

    return marchRes(false, depth, ro + depth*rd, mres.mat);
}

vec3 calcNormal( in vec3 p ) // by iq
{
    const float h = 0.00001;
    #define ZERO (min(iFrame,0))
    vec3 n = vec3(0.0);
    for( int i=ZERO; i<4; i++ )
    {
        vec3 e = 0.5773*(2.0*vec3((((i+3)>>1)&1),((i>>1)&1),(i&1))-1.0);
        n += e*sceneDist(p+e*h);
    }
    return normalize(n);
}

vec4 getColorAtPix(vec2 fc, vec4 m)
{
    vec2 uv = (fc-iResolution.xy*0.5)/iResolution.y;
    vec2 mouse = (m.xy-iResolution.xy*0.5)/iResolution.y*step(0.01, m.z)*3.0;

    vec2 cr = vec2(0.6154729, 0.7853982+iTime*0.2) - mouse.yx;
    vec3 ro = rotY(rotX(vec3(0.1, 0.05, -2.*FOCAL_LEN), cr.x), cr.y);
    vec3 rd = rotY(rotX(normalize(vec3(uv, FOCAL_LEN)), cr.x), cr.y);

    marchRes res = march(ro, rd, 0.001, 100.0, 512);
    vec3 n = calcNormal(res.pos);
    float lighting = dot(max(rot(n, vec3(1,1,0)*0.707106781187, 0.96), 0.0), vec3(0.33))+0.1*max(0., n.z);
    float ao = 1.-pow(0.9-saturate(sceneDist(res.pos+AO_DIST*n)/AO_DIST), AO_POW);

    vec3 envMap = texture(iChannel0, reflect(rd, n), texture(iChannel2, res.pos*0.5).r*10.0).rgb;
    envMap *= envMap;

    res.mat.color = res.mat.color + envMap*1.0;

    return sqrt(displayVar(mix(vec3(0.9), res.mat.color*lighting*mix(1., ao, AO_STR), vec3(res.hit))));
    //return displayVar(ao);
}

vec4 simpleAA(vec2 fc, vec4 m)
{
    vec4 res = vec4(0);
    float st = 2.0/AA;
    for(float x = -1.; x < 1.; x += st) { for(float y = -1.; y < 1.; y += st)
    {
        res += getColorAtPix(fc + (vec2(x,y)+0.5), m);
    }}
    return res/(AA*AA);
}

vec4 stochasticAA(vec2 fc, vec4 m)
{
    vec4 res = vec4(0);
    float st = 1.0/(AA-1.);
    res += getColorAtPix(fc, m);
    if(AA > 1.)
    {
        for(float x = 0.; x < 1.; x += st)
        {
            res += getColorAtPix(fc + (hash22((x+iTime+fc)*25.)-0.5), m);
        }
    }
    return res/AA;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec4 col = stochasticAA(fragCoord, iMouse);
    fragColor = col + displayVar(printFR((fragCoord-iResolution.xy*0.5)/iResolution.y*0.55, iFrameRate));
}

